package br.com.ajudamutua.controller; import br.com.ajudamutua.model.SignedTransparencyReport; import br.com.ajudamutua.service.TransparencyReportService; import org.springframework.web.bind.annotation.*; import java.time.LocalDate; import java.util.*;
@RestController @RequestMapping("/api/v1/transparency/reports") public class TransparencyReportController {private final TransparencyReportService s;public TransparencyReportController(TransparencyReportService s){this.s=s;}public record Generate(LocalDate periodStart,LocalDate periodEnd){} @PostMapping public SignedTransparencyReport generate(@RequestBody Generate in){return s.generate(in.periodStart(),in.periodEnd());}@GetMapping("/latest") public SignedTransparencyReport latest(){return s.latest().orElseThrow(()->new IllegalStateException("Nenhum relatório gerado"));}@GetMapping("/verification") public Map<String,String> verification(){return s.verificationInfo();}}
